#!/usr/bin/env python3
"""Original SH-2 runtime drive diagnostic. MIT: adjacent LICENSE.

ST-162 §§3.4/4.2/4.3/8.2: all commands, polls and result writes execute
inside the guest. Mount an original 100-sector ISO before starting the CPU.
"""
import argparse
import hashlib
from pathlib import Path
import struct
from build_scu import assembler

HERE = Path(__file__).resolve().parent

def store(address, value):
    return f'load {address:#x},r1\nload {value & 0xffffffff:#x},r0\nmov.w r0,@r1\n'

def command(words, name, mailbox):
    source = store(0x25890008, 0xFFFE)
    for i, value in enumerate(words):
        source += store(0x25890018+i*4, value)
    source += f'load 0x25890008,r1\n{name}:\nmov.w @r1,r0\ntst #1,r0\nbt {name}\n'
    for i in range(4):
        source += f'load {0x25890018+i*4:#x},r1\nmov.w @r1,r0\nextu.w r0,r0\nload {mailbox+i*4:#x},r1\nmov.l r0,@r1\n'
    return source

def build():
    s = command([0x0400,1,0,0], 'initialize', 0x06009000)
    s += command([0x1200,0,0,0], 'scan_forward', 0x06009010)
    s += 'forward:\n' + command([0,0,0,0], 'forward_status', 0x06009020)
    s += 'load 170,r2\ncmp/hs r2,r0\nbt forward_done\nbra forward\nnop\nforward_done:\n'
    s += command([0x1201,0,0,0], 'scan_reverse', 0x06009030)
    s += 'reverse:\n' + command([0,0,0,0], 'reverse_status', 0x06009040)
    s += 'load 160,r2\ncmp/hs r2,r0\nbf reverse_done\nbra reverse\nnop\nreverse_done:\n'
    s += command([0x11FF,0xFFFF,0,0], 'pause', 0x06009050)
    s += 'paused:\n' + command([0,0,0,0], 'pause_status', 0x06009060)
    s += 'load 0x06009060,r1\nmov.l @r1,r0\nload 0x0180,r2\ncmp/eq r2,r0\nbt pause_done\nbra paused\nnop\npause_done:\n'
    s += command([0x2001,0,0,0], 'empty_rw', 0x06009070)
    s += command([0x0500,0,0,0], 'open', 0x06009080)
    s += command([0x0400,0xFFFF,0,0], 'close', 0x06009090)
    s += command([0x0200,0,0,0], 'toc', 0x060090A0)
    s += 'load 0x25818000,r1\nmov.l @r1,r0\nload 0x060090E0,r2\nmov.l r0,@r2\n'
    s += command([0x0600,0,0,0], 'end_toc', 0x060090B0)
    s += command([0x5100,0,0,0], 'count', 0x060090C0)
    s += 'load 0x060090F0,r1\nload 0x600d,r0\nmov.l r0,@r1\nsleep\n'
    rom = bytearray(524288)
    struct.pack_into('>II',rom,0,0x200,0x06100000)
    code = assembler.assemble(s,base=0x200)
    assert len(code)<0x5000
    rom[0x200:0x200+len(code)] = code
    text = ['# Original runtime CD drive guest. MIT: adjacent LICENSE.',
            '# Generated by build_cd_drive.py; unspecified ROM bytes are zero.']
    for address in range(0,len(rom),16):
        data = rom[address:address+16]
        if any(data):
            text.append(f'{address:04X} '+' '.join(f'{w:04X}' for w in struct.unpack('>8H',data)))
    return '\n'.join(text)+'\n', hashlib.sha256(rom).hexdigest()

if __name__ == '__main__':
    parser = argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    args = parser.parse_args()
    text,digest=build()
    path=HERE/'cd-drive.hex'
    if args.check: assert path.read_text()==text,'Rebuild cd-drive.hex'
    else: path.write_text(text)
    print(f'{"Verified" if args.check else "Built"} cd-drive.hex; expanded ROM SHA-256 {digest}')
